  "faq.n07Questions": "07 · Ajụjụ",
  "faq.notYetLan": "Ọ bụghị ugbu a. Egwuregwu ọtụtụ ndị LAN n'otu netwọk na-arụ ọrụ taa (kemgbe 0.2.0); e wughị egwuregwu n'ịntanetị.",
  "faq.prototypeWasBuilt": "E wuru ihe nlereanya mbụ n'elu engine Quake III Arena nke mepere emepe (GPL) ma were ụgbọ Elite Dangerous dị ka mkpali. N'ụbọchị nke abụọ, koodu egwuregwu ahụ kwagara n'elu BuB, engine ọhụrụ e dere site na Claude Code; modul egwuregwu ahụ sitere n'ihe nlereanya mbụ ma a gbanwere aha ha. Ntọhapụ 0.3.0 nyere ụdị ụgbọ niile 16 ahụ ọhụrụ. Nyocha nrube isi n'ikike na-enyocha ma koodu ọ bụla ka sitere na GPL mbụ na ma atụmatụ ụgbọ mbụ ahụ dị nso nke ukwuu n'ihe mkpali ha. Nyocha akpaaka nke myirịta nke koodu ahụ megide isi mmalite ihe nlereanya GPL bụ nke a rụrụ na <0/>, nyocha ọkachamara nke ihe ya na-adị otu na-aga n'ihu. Ihe ọ bụla sitere na ya ka a ga-edegharị ma ọ bụ mezie atụmatụ ya. Ruo mgbe nyocha ahụ gwụchara, anyị anaghị ekwu na azịza ya bụ mba.",
  "faq.questions": "Ajụjụ",
  "faq.shipsArtInterface": "Ụgbọ, eserese, interfeesi na ndị ọzọ, dị ka ego si abata. <0>Ndepụta dị n'ibe a<\/0> na-edepụta ihe ọ bụla ma ga-egosi nnọchi ọ bụla na onye na-ese ihe ya.",
  "faq.shipsUpgradesPlanned": "A na-eme atụmatụ ka a nwee ike inweta ụgbọ na mmeziwanye site n'igwu egwuregwu ma ọ bụ zụta ha. Etu ụgbọ a kwụrụ ụgbọ si anọ n'ụzọ ziri ezi n'ọgụ onye egwuregwu megide onye egwuregwu ka a na-ahazi.",
  "faq.thatPlanFree": "Nke ahụ bụ atụmatụ: ọ bụ n'efu ịgba ya, ya na ego n'egwuregwu na ihe ịchọ mma ma ọ masịrị gị. E wughị ya.",
  "faq.wasAnyoneS": "E kopịrị ọrụ onye ọ bụla?",
